WITH household_sales AS ( SELECT hd.hd_demo_sk, ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound, SUM(ss.ss_ext_sales_price) AS household_total_sales, SUM(ss.ss_net_profit) AS household_total_profit, COUNT(*) AS transaction_count, cd.cd_dep_count, cd.cd_dep_employed_count, cd.cd_dep_college_count FROM store_sales ss JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk JOIN customer_demographics cd ON ss.ss_cdemo_sk = cd.cd_demo_sk GROUP BY hd.hd_demo_sk, ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound, cd.cd_dep_count, cd.cd_dep_employed_count, cd.cd_dep_college_count ) SELECT hd_demo_sk, ib_income_band_sk, ib_lower_bound, ib_upper_bound, household_total_sales, household_total_profit, transaction_count, CASE WHEN household_total_sales >= 500000 THEN 'Platinum' WHEN household_total_sales >= 200000 THEN 'Gold' WHEN household_total_sales >= 50000 THEN 'Silver' ELSE 'Bronze' END AS sales_tier, ROW_NUMBER() OVER (PARTITION BY ib_income_band_sk ORDER BY household_total_sales DESC) AS sales_rank, LAG(household_total_sales) OVER (PARTITION BY ib_income_band_sk ORDER BY household_total_sales DESC) AS previous_household_sales, household_total_sales - COALESCE(LAG(household_total_sales) OVER (PARTITION BY ib_income_band_sk ORDER BY household_total_sales DESC),0) AS sales_diff_from_previous FROM household_sales WHERE ib_upper_bound IS NOT NULL ORDER BY ib_lower_bound, sales_rank LIMIT 20
